CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, email_normalized TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'deleted')), created_at INTEGER NOT NULL, deleted_at INTEGER );
CREATE TABLE IF NOT EXISTS identities ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK (provider IN ('google', 'dev')), provider_subject TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE (provider, provider_subject) );
CREATE INDEX IF NOT EXISTS ix_identities_user ON identities(user_id);
CREATE TABLE IF NOT EXISTS sessions ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS ix_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS oauth_states ( state_hash TEXT PRIMARY KEY, code_verifier TEXT NOT NULL, nonce TEXT NOT NULL, return_to TEXT NOT NULL DEFAULT '/', expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS user_profiles ( user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, certificate_name TEXT CHECK (certificate_name IS NULL OR length(certificate_name) <= 120), village_role TEXT CHECK (village_role IS NULL OR village_role IN ('perbekel', 'sekdes', 'kaur', 'kasi', 'kawil', 'operator_sid', 'bpd', 'kader', 'lainnya')), village_name TEXT CHECK (village_name IS NULL OR length(village_name) <= 80), district TEXT CHECK (district IS NULL OR length(district) <= 80), regency TEXT CHECK (regency IS NULL OR length(regency) <= 80), privacy_consent_at INTEGER, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS system_roles ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('learner', 'mentor', 'content_editor', 'admin', 'super_admin')), assigned_by TEXT, assigned_at INTEGER NOT NULL, PRIMARY KEY (user_id, role) );
CREATE TABLE IF NOT EXISTS user_accommodations ( user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, copy_deterrence_exempt INTEGER NOT NULL DEFAULT 0 CHECK (copy_deterrence_exempt IN (0, 1)), note TEXT CHECK (note IS NULL OR length(note) <= 300), set_by TEXT NOT NULL, set_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS ui_preferences ( user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, font_scale REAL NOT NULL DEFAULT 1 CHECK (font_scale BETWEEN 1 AND 2), contrast_mode TEXT NOT NULL DEFAULT 'default' CHECK (contrast_mode IN ('default', 'high')), updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS courses ( id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE CHECK (slug NOT GLOB '*[^a-z0-9-]*' AND length(slug) BETWEEN 3 AND 80), title TEXT NOT NULL CHECK (length(title) BETWEEN 3 AND 160), description TEXT NOT NULL DEFAULT '', visibility TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'private')), status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')), current_version_id TEXT, enrollment_open_at INTEGER, enrollment_close_at INTEGER, access_starts_at INTEGER, access_expires_at INTEGER, access_duration_days INTEGER CHECK (access_duration_days IS NULL OR access_duration_days > 0), learning_session_ttl_seconds INTEGER NOT NULL DEFAULT 7200 CHECK (learning_session_ttl_seconds BETWEEN 300 AND 86400), created_by TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS course_versions ( id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, version_no INTEGER NOT NULL CHECK (version_no >= 1), status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'superseded')), published_at INTEGER, published_by TEXT, created_by TEXT, created_at INTEGER NOT NULL, UNIQUE (course_id, version_no) );
CREATE UNIQUE INDEX IF NOT EXISTS ux_course_versions_one_draft ON course_versions(course_id) WHERE status = 'draft';
CREATE TABLE IF NOT EXISTS lessons ( id TEXT PRIMARY KEY, course_version_id TEXT NOT NULL REFERENCES course_versions(id) ON DELETE CASCADE, lesson_key TEXT NOT NULL, seq INTEGER NOT NULL CHECK (seq >= 1), title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 160), summary TEXT NOT NULL DEFAULT '', content_type TEXT NOT NULL CHECK (content_type IN ('html', 'slides', 'pdf', 'youtube')), content_source TEXT NOT NULL DEFAULT '', content_json TEXT NOT NULL DEFAULT '[]', file_key TEXT, youtube_id TEXT CHECK (youtube_id IS NULL OR (length(youtube_id) = 11 AND youtube_id NOT GLOB '*[^A-Za-z0-9_-]*')), required_active_seconds INTEGER NOT NULL DEFAULT 300 CHECK (required_active_seconds BETWEEN 0 AND 36000), is_required INTEGER NOT NULL DEFAULT 1 CHECK (is_required IN (0, 1)), UNIQUE (course_version_id, seq), UNIQUE (course_version_id, lesson_key) );
CREATE TABLE IF NOT EXISTS lesson_sources ( id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, section_key TEXT NOT NULL, approved_text TEXT NOT NULL, source_revision INTEGER NOT NULL DEFAULT 1, approved_by TEXT, approved_at INTEGER );
CREATE TABLE IF NOT EXISTS role_recommendations ( village_role TEXT NOT NULL CHECK (village_role IN ('perbekel', 'sekdes', 'kaur', 'kasi', 'kawil', 'operator_sid', 'bpd', 'kader', 'lainnya')), course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, priority INTEGER NOT NULL DEFAULT 1, PRIMARY KEY (village_role, course_id) );
CREATE TABLE IF NOT EXISTS mentor_assignments ( mentor_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, assigned_by TEXT NOT NULL, assigned_at INTEGER NOT NULL, PRIMARY KEY (mentor_id, course_id) );
CREATE TABLE IF NOT EXISTS enrollments ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_id TEXT NOT NULL REFERENCES courses(id), course_version_id TEXT NOT NULL REFERENCES course_versions(id), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'expired', 'withdrawn')), started_at INTEGER NOT NULL, expires_at INTEGER, completed_at INTEGER, UNIQUE (user_id, course_id) );
CREATE TABLE IF NOT EXISTS learning_sessions ( id TEXT PRIMARY KEY, enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, lesson_id TEXT NOT NULL REFERENCES lessons(id), started_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, last_heartbeat_at INTEGER NOT NULL, accumulated_active_seconds INTEGER NOT NULL DEFAULT 0 CHECK (accumulated_active_seconds >= 0), status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'expired', 'closed')) );
CREATE INDEX IF NOT EXISTS ix_learning_sessions_user_lesson ON learning_sessions(user_id, lesson_id, status);
CREATE TABLE IF NOT EXISTS lesson_progress ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, lesson_id TEXT NOT NULL REFERENCES lessons(id), enrollment_id TEXT NOT NULL REFERENCES enrollments(id) ON DELETE CASCADE, active_seconds INTEGER NOT NULL DEFAULT 0 CHECK (active_seconds >= 0), content_accessed_at INTEGER, completed_at INTEGER, last_accessed_at INTEGER, PRIMARY KEY (user_id, lesson_id) );
CREATE TABLE IF NOT EXISTS assessments ( id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, title TEXT NOT NULL CHECK (length(title) BETWEEN 3 AND 160), instructions TEXT NOT NULL DEFAULT '', time_limit_seconds INTEGER NOT NULL DEFAULT 900 CHECK (time_limit_seconds BETWEEN 60 AND 14400), passing_score_pct INTEGER NOT NULL DEFAULT 70 CHECK (passing_score_pct BETWEEN 0 AND 100), max_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_attempts BETWEEN 1 AND 20), cooldown_seconds INTEGER NOT NULL DEFAULT 0 CHECK (cooldown_seconds BETWEEN 0 AND 604800), mcq_count INTEGER NOT NULL DEFAULT 10 CHECK (mcq_count BETWEEN 0 AND 100), essay_count INTEGER NOT NULL DEFAULT 0 CHECK (essay_count BETWEEN 0 AND 10), grace_seconds INTEGER NOT NULL DEFAULT 20 CHECK (grace_seconds BETWEEN 0 AND 120), is_required INTEGER NOT NULL DEFAULT 1 CHECK (is_required IN (0, 1)), version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, UNIQUE (lesson_id) );
CREATE TABLE IF NOT EXISTS assessment_policies ( assessment_id TEXT PRIMARY KEY REFERENCES assessments(id) ON DELETE CASCADE, version INTEGER NOT NULL DEFAULT 1, exam_copy_deterrence_enabled INTEGER NOT NULL DEFAULT 1 CHECK (exam_copy_deterrence_enabled IN (0, 1)), ai_lock_enabled INTEGER NOT NULL DEFAULT 1 CHECK (ai_lock_enabled = 1), accessibility_exemption_policy TEXT NOT NULL DEFAULT 'per_user' CHECK (accessibility_exemption_policy IN ('per_user', 'none')), hide_lesson_links_during_exam INTEGER NOT NULL DEFAULT 1 CHECK (hide_lesson_links_during_exam IN (0, 1)), updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS questions ( id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK (type IN ('mcq', 'essay')), stem TEXT NOT NULL CHECK (length(stem) BETWEEN 5 AND 4000), difficulty INTEGER NOT NULL DEFAULT 2 CHECK (difficulty BETWEEN 1 AND 3), topic TEXT NOT NULL DEFAULT 'umum', points INTEGER NOT NULL DEFAULT 1 CHECK (points BETWEEN 1 AND 100), version INTEGER NOT NULL DEFAULT 1, rubric_json TEXT, model_answer TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)), created_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS ix_questions_pool ON questions(assessment_id, type, is_active);
CREATE TABLE IF NOT EXISTS question_options ( id TEXT PRIMARY KEY, question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, body TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 1000), is_correct INTEGER NOT NULL DEFAULT 0 CHECK (is_correct IN (0, 1)), version INTEGER NOT NULL DEFAULT 1 );
CREATE INDEX IF NOT EXISTS ix_question_options_q ON question_options(question_id);
CREATE TABLE IF NOT EXISTS attempts ( id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, enrollment_id TEXT NOT NULL REFERENCES enrollments(id), assessment_version INTEGER NOT NULL, attempt_no INTEGER NOT NULL CHECK (attempt_no >= 1), started_at INTEGER NOT NULL, deadline_at INTEGER NOT NULL, grace_seconds INTEGER NOT NULL, submitted_at INTEGER, finalized_at INTEGER, status TEXT NOT NULL CHECK (status IN ('in_progress', 'submitted', 'expired', 'voided')), mcq_score INTEGER, mcq_max INTEGER, essay_score INTEGER, essay_max INTEGER, final_score_pct REAL, passing_score_pct INTEGER NOT NULL, result_status TEXT NOT NULL DEFAULT 'pending' CHECK (result_status IN ('pending', 'passed', 'failed', 'pending_review')), review_required INTEGER NOT NULL DEFAULT 0 CHECK (review_required IN (0, 1)), copy_deterrence_active INTEGER NOT NULL DEFAULT 1 CHECK (copy_deterrence_active IN (0, 1)), CHECK (deadline_at > started_at), UNIQUE (user_id, assessment_id, attempt_no) );
CREATE UNIQUE INDEX IF NOT EXISTS ux_attempts_one_active_per_user ON attempts(user_id) WHERE status = 'in_progress';
CREATE INDEX IF NOT EXISTS ix_attempts_user_assessment ON attempts(user_id, assessment_id);
CREATE INDEX IF NOT EXISTS ix_attempts_status_deadline ON attempts(status, deadline_at);
CREATE TABLE IF NOT EXISTS attempt_questions ( id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id) ON DELETE CASCADE, question_id TEXT NOT NULL REFERENCES questions(id), question_version INTEGER NOT NULL, sequence INTEGER NOT NULL CHECK (sequence >= 1), type TEXT NOT NULL CHECK (type IN ('mcq', 'essay')), stem_snapshot TEXT NOT NULL, points INTEGER NOT NULL, options_snapshot_json TEXT NOT NULL DEFAULT '[]', answer_key_snapshot TEXT, UNIQUE (attempt_id, sequence) );
CREATE TABLE IF NOT EXISTS answers ( id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id) ON DELETE CASCADE, attempt_question_id TEXT NOT NULL UNIQUE REFERENCES attempt_questions(id) ON DELETE CASCADE, selected_option_key TEXT, essay_text TEXT CHECK (essay_text IS NULL OR length(essay_text) <= 20000), saved_at INTEGER NOT NULL, finalized_at INTEGER, mcq_correct INTEGER CHECK (mcq_correct IS NULL OR mcq_correct IN (0, 1)), essay_score INTEGER, essay_feedback TEXT, graded_by TEXT, graded_at INTEGER );
CREATE INDEX IF NOT EXISTS ix_answers_attempt ON answers(attempt_id);
CREATE TABLE IF NOT EXISTS essay_reviews ( id TEXT PRIMARY KEY, answer_id TEXT NOT NULL REFERENCES answers(id) ON DELETE CASCADE, reviewer_id TEXT NOT NULL REFERENCES users(id), rubric_scores_json TEXT NOT NULL, score INTEGER NOT NULL, feedback TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', decided_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS appeals ( id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, reason TEXT NOT NULL CHECK (length(reason) BETWEEN 10 AND 2000), status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'rejected')), created_at INTEGER NOT NULL, resolved_by TEXT, resolved_at INTEGER, resolution TEXT );
CREATE UNIQUE INDEX IF NOT EXISTS ux_appeals_one_open ON appeals(attempt_id) WHERE status = 'open';
CREATE TABLE IF NOT EXISTS ai_usage ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, lesson_id TEXT, date_key TEXT NOT NULL, purpose TEXT NOT NULL, request_count INTEGER NOT NULL DEFAULT 0, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, estimated_cost REAL NOT NULL DEFAULT 0, UNIQUE (user_id, date_key, purpose) );
CREATE TABLE IF NOT EXISTS admin_audit_logs ( id TEXT PRIMARY KEY, actor_user_id TEXT NOT NULL, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, created_at INTEGER NOT NULL, metadata_redacted TEXT NOT NULL DEFAULT '{}' );
CREATE INDEX IF NOT EXISTS ix_audit_created ON admin_audit_logs(created_at);
CREATE TABLE IF NOT EXISTS security_events ( id TEXT PRIMARY KEY, user_id TEXT, type TEXT NOT NULL, created_at INTEGER NOT NULL, metadata_minimal TEXT NOT NULL DEFAULT '{}' );
CREATE INDEX IF NOT EXISTS ix_security_events_created ON security_events(created_at);
CREATE TABLE IF NOT EXISTS rate_limits ( key TEXT NOT NULL, window_start INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (key, window_start) );
CREATE TABLE IF NOT EXISTS d1_migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
INSERT OR IGNORE INTO d1_migrations (name) VALUES ('0001_init.sql');
